var r={"C\xF3digo de vendedor no v\xE1lido":"El c\xF3digo no existe o pertenece a un usuario POS.","No hay corte global abierto en la sucursal":"No hay corte abierto en esta sucursal. La terminal de cobranza debe abrir el corte del d\xEDa.","Solo terminales de tipo COBRANZA pueden abrir el corte global":"Solo la terminal de cobranza puede abrir el corte del d\xEDa.","La orden no est\xE1 pendiente de cobro":"Esta venta ya fue cobrada o no est\xE1 pendiente.","No se puede cobrar una orden en cola":"Esta venta est\xE1 en cola. Cobranza debe abrir el corte del d\xEDa para asignarla antes de cobrar.","No se puede cambiar el tipo POS de un usuario con corte global abierto":"No se puede modificar este usuario COBRANZA mientras tenga un corte abierto.","No se puede cambiar el tipo POS ni la sucursal mientras hay un corte global abierto. Cierra el corte primero.":"Cierra el corte de esta sucursal antes de cambiar.","Este cliente no tiene cr\xE9dito activo con esta raz\xF3n social":"Este cliente no tiene cr\xE9dito activo con esta raz\xF3n social","Selecciona al menos dos formas de pago":"Selecciona al menos dos formas de pago","Completa RFC, raz\xF3n social y CP del cliente":"Completa RFC, raz\xF3n social y CP del cliente","Esta orden ya fue cobrada":"Esta orden ya fue cobrada"};function n(a){if(!a)return"Ocurri\xF3 un error en el POS.";let o=r[a];if(o)return o;let e=a.toLowerCase();return e.includes("cr\xE9dito insuficiente")||e.includes("credito insuficiente")?a.startsWith("Cr\xE9dito insuficiente")?a:`Cr\xE9dito insuficiente. ${a}`:e.includes("no tiene cr\xE9dito")||e.includes("no tiene credito")?"Este cliente no tiene cr\xE9dito activo con esta raz\xF3n social":e.includes("ya fue cobrada")||e.includes("ya est\xE1 cobrada")||e.includes("ya esta cobrada")?"Esta orden ya fue cobrada":e.includes("al menos dos")?"Selecciona al menos dos formas de pago":e.includes("rfc")&&(e.includes("raz\xF3n social")||e.includes("razon social"))?"Completa RFC, raz\xF3n social y CP del cliente":a.startsWith("El c\xF3digo")&&a.includes("ya est\xE1 asignado")?"Ese c\xF3digo de vendedor ya est\xE1 asignado a otro usuario.":a}export{n as a};
